function pruefePasswort(pw) {
  if (pw.length < 10) {
    return false;
  }
  let ziffer = false;
  let gross = false;
  for (let i = 0; i <= pw.length - 1; i++) {
    let c = pw.charAt(i);
    if (c >= "0" && c <= "9") { ziffer = true; }
