// a) Selection Sort
for (let i = 0; i <= artikel.length - 2; i++) {
  let maxPos = i;
  for (let j = i + 1; j <= artikel.length - 1; j++) {
    if (artikel[j].getPreis() > artikel[maxPos].getPreis()) {
      maxPos = j;
    }
  }
  let tmp = artikel[i];
  artikel[i] = artikel[maxPos];
  artikel[maxPos] = tmp;
}

// b) Insertion Sort
for (let i = 1; i <= artikel.length - 1; i++) {
  let aktuell = artikel[i];
  let j = i - 1;
  while (j >= 0 && artikel[j].getPreis() < aktuell.getPreis()) {
    artikel[j + 1] = artikel[j];
    j = j - 1;
  }
  artikel[j + 1] = aktuell;
}

// c) Insertion Sort: Bei fast sortierten Daten kaum innere Durchläufe, nahe O(n).
//    Selection Sort sucht immer den ganzen Rest ab und bleibt bei O(n²).

